CREATE TYPE role AS ENUM ('SUPER_ADMIN','LIBRARY_STAFF','PHD_SCHOLAR'); CREATE TYPE location AS ENUM ('A_BLOCK','B_BLOCK','ALL'); CREATE TYPE hours_status AS ENUM ('Ongoing','Completed'); CREATE TYPE report_status AS ENUM ('Not Issued','Issued','With Student','Faculty Took'); CREATE TYPE visit_status AS ENUM ('Inside','Completed Visit');
CREATE SEQUENCE library_record_number_seq START 1001;
CREATE TABLE users (id serial PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,role role NOT NULL,location location NOT NULL DEFAULT 'ALL',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE students(id serial PRIMARY KEY,register_number text NOT NULL UNIQUE,name text NOT NULL,programme text,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX students_register_number_idx ON students(register_number);
CREATE TABLE library_records(id serial PRIMARY KEY,record_number integer NOT NULL UNIQUE,student_id integer NOT NULL REFERENCES students(id),record_date date NOT NULL,location location NOT NULL,reason_type text NOT NULL,additional_details text,assignment_faculty_name text NOT NULL,assigned_requirement text NOT NULL,hours_status hours_status NOT NULL DEFAULT 'Ongoing',completed_at timestamptz,completed_by integer REFERENCES users(id),report_letter_number text,report_submitted_date date NOT NULL,report_status report_status NOT NULL DEFAULT 'Not Issued',report_faculty_name text,notes text,cancelled_at timestamptz,cancellation_reason text,created_by integer NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX records_filters_idx ON library_records(location,record_date,record_number DESC);
CREATE TABLE record_hours_history(id serial PRIMARY KEY,record_id integer NOT NULL REFERENCES library_records(id),kind text NOT NULL,amount text NOT NULL,note text,location location NOT NULL,added_by integer NOT NULL REFERENCES users(id),effective_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE record_report_history(id serial PRIMARY KEY,record_id integer NOT NULL REFERENCES library_records(id),status report_status NOT NULL,report_faculty_name text,note text,changed_by integer NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE record_attachments(id serial PRIMARY KEY,record_id integer NOT NULL REFERENCES library_records(id),original_filename text NOT NULL,blob_key text NOT NULL,content_type text NOT NULL,size integer NOT NULL,uploaded_by integer NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE record_replacements(id serial PRIMARY KEY,old_record_id integer NOT NULL REFERENCES library_records(id),new_record_id integer NOT NULL REFERENCES library_records(id),reason text NOT NULL,created_by integer NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE circulation_visits(id serial PRIMARY KEY,register_number text NOT NULL,location location NOT NULL,entry_at timestamptz NOT NULL DEFAULT now(),exit_at timestamptz,source text NOT NULL DEFAULT 'Automatic',status visit_status NOT NULL DEFAULT 'Inside',record_id integer REFERENCES library_records(id),created_by integer NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE audit_logs(id serial PRIMARY KEY,user_id integer REFERENCES users(id),role role NOT NULL,action text NOT NULL,entity text NOT NULL,entity_id text NOT NULL,description text NOT NULL,old_value jsonb,new_value jsonb,location location,created_at timestamptz NOT NULL DEFAULT now());
